390	// What it does, in the order that keeps a half-applied run readable:
391	//   1. moves `.claudinite-checks.json` to `.claudinite-settings.json` (git sees a
392	//      rename, so the file's history follows it);
393	//   2. lifts the retired `claudinite` block's `engineVersion` to the top level and
394	//      its `packVersions` onto the entry of each pack they price, dropping any key
395	//      no entry names — a version for a pack the declaration does not carry prices
396	//      nothing, and inventing an entry for it would activate a pack nobody declared;
397	//   3. turns `maintenance.delivery: review` into
398	//      `dailyClaudiniteUpdatesRequirePrReview: true` and drops the block — including
399	//      `mechanism`, whose only rival was deleted in #768 Phase 5, so it had exactly
400	//      one possible answer for every member that could still ask;
401	//   4. renames `taskScheduler.endpoints` to `agenticTaskInvocationEndpoints`.
402	//
403	// IDEMPOTENT BY CONSTRUCTION: every step is stated as "if the retired shape is
404	// there", so a second run finds nothing and writes nothing. It reads the member's
405	// OWN file and rewrites only the keys it names — a project's rules, accept entries,
406	// pack config and answers pass through untouched, and key ORDER is preserved for
407	// everything it does not move, because this is a file people read.
408	export async function applySettingsReshape(migration, { read, write, move, exists }) {
409	  if (!migration.reshapeSettings) return [];
410	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
411	  const file = await declarationFile(read);
412	  if (file == null) return [];
413	  const raw = await read(file);
414	  let config;
415	  try { config = JSON.parse(raw); } catch { return []; }
416	  if (config === null || typeof config !== 'object' || Array.isArray(config)) return [];
417	
418	  const done = [];
419	
420	  // 1. The name. Moved before anything is written, so the write below lands on the
421	  //    renamed file and git records one rename rather than a delete and an add.
422	  if (file === LEGACY_SETTINGS_FILE) {
423	    if (await exists(SETTINGS_FILE)) return [];     // both names present — a repair no record should guess at
424	    await move(LEGACY_SETTINGS_FILE, SETTINGS_FILE);
425	    done.push(`${LEGACY_SETTINGS_FILE} -> ${SETTINGS_FILE}`);
426	  }
427	
428	  // 2. The versions, onto the shape that holds them now.
429	  let next = config;
430	  if (next[LEGACY_STAMP_KEY] !== undefined) {
431	    const { engineVersion, packVersions } = installedVersions(next);
432	    next = withInstalledVersions(next, { engineVersion, packVersions });
433	    delete next[LEGACY_STAMP_KEY];
434	    done.push(`${SETTINGS_FILE}: engineVersion and per-pack versions lifted out of "${LEGACY_STAMP_KEY}"`);
435	  }
436	
437	  // 3. The delivery override. Only `review` carries an intent worth keeping; every
438	  //    other value said what the absent key now says.
439	  if (next.maintenance !== undefined) {
440	    const delivery = String(next.maintenance?.delivery ?? '').trim();
441	    const { maintenance, ...rest } = next;
442	    next = rest;
443	    if (delivery === 'review' || delivery === 'pr') {
444	      next.dailyClaudiniteUpdatesRequirePrReview = true;
445	      done.push(`${SETTINGS_FILE}: maintenance.delivery "${delivery}" -> dailyClaudiniteUpdatesRequirePrReview: true`);
446	    } else {
447	      done.push(`${SETTINGS_FILE}: dropped the retired "maintenance" block`);
448	    }
449	  }

