  [BLOCKED, STATUS_BLOCKED],
  [READY, STATUS_READY],
  [EXECUTING, STATUS_RUNNING_EXECUTOR],
  [AGENT, STATUS_RUNNING_AGENT],
  [TASK_DONE, STATUS_DONE], [OUTCOME_DONE, STATUS_DONE],
  [TASK_OBSOLETE, STATUS_REJECTED], [OUTCOME_OBSOLETE, STATUS_REJECTED],
]);

